cd /workspace && node -e "
const XLSX = require('xlsx');
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, BorderStyle, AlignmentType, HeadingLevel } = require('docx');
const fs = require('fs');

// Read data
const wb = XLSX.readFile('/workspace/testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);
const myOrders = data.filter(r => r.Customer === 'Maya Chen');
const confirmed = myOrders.filter(r => r.Status === 'confirmed');
const cancelled = myOrders.filter(r => r.Status === 'cancelled');
const totalPaid = myOrders.reduce((s, r) => s + r['Total Paid'], 0);
const confirmedTotal = confirmed.reduce((s, r) => s + r['Total Paid'], 0);
const cancelledTotal = cancelled.reduce((s, r) => s + r['Total Paid'], 0);
const avgOrder = (confirmedTotal / confirmed.length).toFixed(2);

// Count items across all orders
const itemCounts = {};
myOrders.forEach(r => {
  r.Items.split(', ').forEach(item => {
    itemCounts[item] = (itemCounts[item] || 0) + 1;
  });
});
const sortedItems = Object.entries(itemCounts).sort((a, b) => b[1] - a[1]);

// Helpers
const border = { style: BorderStyle.SINGLE, size: 1, color: '999999' };
const cellBorders = { top: border, bottom: border, left: border, right: border };

function makeHeaderCell(text) {
  return new TableCell({
    borders: cellBorders,
    children: [new Paragraph({ children: [new TextRun({ text, bold: true, size: 20, font: 'Calibri' })], alignment: AlignmentType.CENTER })],
  });
}
function makeCell(text, align) {
  return new TableCell({
    borders: cellBorders,
    children: [new Paragraph({ children: [new TextRun({ text: String(text), size: 20, font: 'Calibri' })], alignment: align || AlignmentType.LEFT })],
  });
}

// Order detail table
const orderTableRows = [
  new TableRow({ children: ['Order ID', 'Date', 'Status', 'Items', 'Total Paid'].map(h => makeHeaderCell(h)) }),
  ...myOrders.map(r => new TableRow({
    children: [
      makeCell(r['Order ID']),
      makeCell(r.Date),
      makeCell(r.Status),
      makeCell(r.Items),
      makeCell('\$' + r['Total Paid'], AlignmentType.RIGHT),
    ]
  }))
];

// Item frequency table
const itemTableRows = [
  new TableRow({ children: ['Item', 'Times Ordered'].map(h => makeHeaderCell(h)) }),
  ...sortedItems.map(([item, count]) => new TableRow({
    children: [makeCell(item), makeCell(String(count), AlignmentType.CENTER)]
  }))
];

// Build document
const doc = new Document({
  sections: [{
    children: [
      new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun({ text: 'Order Analysis — Maya Chen', bold: true })] }),
      new Paragraph({ children: [new TextRun({ text: 'Generated from order_summary.xlsx', italics: true, size: 20, color: '666666' })] }),
      new Paragraph({ text: '' }),

      // Summary section
      new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text: 'Summary', bold: true })] }),
      new Paragraph({ children: [new TextRun({ text: 'Total Orders: ', bold: true, size: 22 }), new TextRun({ text: String(myOrders.length), size: 22 })] }),
      new Paragraph({ children: [new TextRun({ text: 'Confirmed: ', bold: true, size: 22 }), new TextRun({ text: String(confirmed.length), size: 22 })] }),
      new Paragraph({ children: [new TextRun({ text: 'Cancelled: ', bold: true, size: 22 }), new TextRun({ text: String(cancelled.length), size: 22 })] }),
      new Paragraph({ children: [new TextRun({ text: 'Total Paid (all): ', bold: true, size: 22 }), new TextRun({ text: '\$' + totalPaid, size: 22 })] }),
      new Paragraph({ children: [new TextRun({ text: 'Total Paid (confirmed): ', bold: true, size: 22 }), new TextRun({ text: '\$' + confirmedTotal, size: 22 })] }),
      new Paragraph({ children: [new TextRun({ text: 'Total Paid (cancelled): ', bold: true, size: 22 }), new TextRun({ text: '\$' + cancelledTotal, size: 22 })] }),
      new Paragraph({ children: [new TextRun({ text: 'Average Confirmed Order Value: ', bold: true, size: 22 }), new TextRun({ text: '\$' + avgOrder, size: 22 })] }),
      new Paragraph({ text: '' }),

      // Order details
      new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text: 'Order Details', bold: true })] }),
      new Table({ rows: orderTableRows, width: { size: 100, type: WidthType.PERCENTAGE } }),
      new Paragraph({ text: '' }),

      // Item frequency
      new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text: 'Most Ordered Items', bold: true })] }),
      new Table({ rows: itemTableRows, width: { size: 70, type: WidthType.PERCENTAGE } }),
      new Paragraph({ text: '' }),

      // Key observations
      new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text: 'Key Observations', bold: true })] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: 'You placed 7 orders on 2026-09-02, making you the most active customer in the dataset.', size: 22 })] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: '5 out of 7 orders were confirmed (71.4% confirmation rate), while 2 were cancelled.', size: 22 })] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: 'Your confirmed orders total \$' + confirmedTotal + ', with an average value of \$' + avgOrder + ' per order.', size: 22 })] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: 'The cancelled orders (ORD-6C71B1 and ORD-12AAA3) totalled \$' + cancelledTotal + ' in lost spend.', size: 22 })] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: 'Your highest-value order was ORD-CCC96C at \$201, which included the Aurora Smart Desk Lamp Pro.', size: 22 })] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: 'The LogiTech Wireless Mouse M310 and OXO SoftWorks 3-Piece Mixing Bowl Set are your most frequently ordered items, each appearing in 3 orders.', size: 22 })] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: 'Your orders span a mix of electronics, kitchen, and home categories.', size: 22 })] }),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/workspace/data/maya_chen_order_analysis.docx', buf);
  console.log('Document saved successfully!');
  console.log('Size:', buf.length, 'bytes');
});
"
